<script lang="ts">
  /**
   * Read-only channel visibility for the operator: bound routes, recent
   * inbound messages (with transcript states) and consumer cursors, plus the
   * "Conectar WhatsApp" block — the assistant instance's connection state and
   * its pairing QR, regenerated by the server over loopback on demand.
   * Nothing in this section can advance a cursor, replay a delivery or send.
   */
  import { RefreshCw } from "@lucide/svelte";
  import Button from "./Button.svelte";
  import {
    ChannelsClient,
    type ChannelsView,
    type EvoQr,
    type EvoStatus,
  } from "../channelsClient";

  let { open = false }: { open?: boolean } = $props();

  const client = new ChannelsClient();
  let view = $state<ChannelsView | null>(null);
  let error = $state("");
  let evo = $state<EvoStatus | null>(null);
  let qr = $state<EvoQr | null>(null);
  let qrBusy = $state(false);
  let qrError = $state("");
  let poller: ReturnType<typeof setInterval> | undefined;

  async function load() {
    try {
      view = await client.inbox();
      error = "";
    } catch (e) {
      error = (e as Error).message;
    }
    try {
      evo = await client.evoStatus();
    } catch {
      evo = null;
    }
  }

  async function refreshQr() {
    if (qrBusy) return;
    qrBusy = true;
    qrError = "";
    try {
      qr = await client.evoQr();
      if (qr.error && qr.error !== "already_connected") qrError = qr.error === "qr_rate_limited" ? "Espera unos segundos y vuelve a intentarlo." : "QR no disponible ahora.";
      else if (qr.error === "already_connected") qrError = "";
    } catch (e) {
      qrError = (e as Error).message;
    } finally {
      qrBusy = false;
    }
  }

  $effect(() => {
    if (!open) return;
    void load();
    poller = setInterval(() => { void load(); }, 10_000);
    return () => {
      if (poller) clearInterval(poller);
      poller = undefined;
    };
  });

  const stateLabel = (state?: string) =>
    ({ connected: "Conectado", connecting: "Conectando…", qr: "Esperando escaneo del QR", disconnected: "Desconectado", unreachable: "weai-mini no responde (loopback)" } as Record<string, string>)[state ?? ""] ?? "Sin configurar";

  function time(ts: number) {
    if (!ts) return "";
    return new Date(ts).toLocaleTimeString();
  }
</script>

<section class="mb-3 rounded-lg border border-line bg-raised/40 p-3" aria-label="Canales">
  <div class="flex items-center justify-between gap-2">
    <h3 class="text-[12.5px] font-medium text-ink">Canales</h3>
    <span class="text-[10.5px] text-ink-faint">Solo lectura</span>
  </div>

  {#if error}
    <p role="status" class="mt-2 text-[11.5px] leading-5 text-warn">{error}. Reintentando…</p>
  {:else if !view}
    <p role="status" class="mt-2 text-[11.5px] text-ink-muted">Leyendo canal…</p>
  {:else if !view.configured}
    <p class="mt-2 text-[11.5px] leading-5 text-ink-muted">Sin almacén de canal configurado en este host.</p>
  {/if}

  {#if view?.configured}
    <div class="mt-2">
      <h4 class="text-[11px] font-medium text-ink-muted">Rutas enlazadas ({view.bindings.length})</h4>
      {#if !view.bindings.length}
        <p class="mt-1 text-[11px] text-ink-faint">Ninguna ruta enlazada todavía.</p>
      {:else}
        <ul class="mt-1 flex flex-col gap-1">
          {#each view.bindings as b (b.channel + b.account + b.thread)}
            <li class="rounded-md border border-line/70 px-2 py-1 text-[10.5px] leading-4">
              <span class="font-medium text-ink">{b.channel}</span>
              <span class="text-ink-muted"> · {b.account} · hilo {b.thread}</span>
              <span class="block text-ink-faint">→ sesión {b.session} · proyecto {b.project}</span>
              <span class="block text-ink-faint">Permitidos: {b.allowedSenders.join(", ")}</span>
            </li>
          {/each}
        </ul>
      {/if}
    </div>

    <div class="mt-3">
      <h4 class="text-[11px] font-medium text-ink-muted">Mensajes recientes ({view.messages.length} de seq {view.lastSeq})</h4>
      {#if !view.messages.length}
        <p class="mt-1 text-[11px] text-ink-faint">Ningún mensaje aceptado todavía.</p>
      {:else}
        <ul class="mt-1 flex flex-col gap-1">
          {#each view.messages as m (m.seq)}
            <li class="rounded-md border border-line/70 px-2 py-1 text-[10.5px] leading-4">
              <span class="font-medium text-ink">#{m.seq}</span>
              <span class="text-ink-muted"> {m.sender} · {time(m.receivedAt)}</span>
              <span class="block break-words text-ink-muted">{m.text}{m.truncated ? "…" : ""}</span>
              {#if m.attachments.length}
                <span class="block text-ink-faint">
                  Adjuntos: {m.attachments.map(a => `${a.kind}${a.transcriptionState ? ` (${a.transcriptionState})` : ""}`).join(", ")}
                </span>
              {/if}
              <span class="block text-ink-faint">→ {m.session} · {m.project}</span>
            </li>
          {/each}
        </ul>
      {/if}
    </div>

    <div class="mt-3">
      <h4 class="text-[11px] font-medium text-ink-muted">Consumidores</h4>
      {#if !view.consumers.length}
        <p class="mt-1 text-[11px] text-ink-faint">Ninguno registrado.</p>
      {:else}
        <ul class="mt-1 flex flex-col gap-1">
          {#each view.consumers as c (c.consumer)}
            <li class="text-[10.5px] leading-4">
              <span class="text-ink">{c.consumer}</span>
              <span class="text-ink-muted"> · cursor {c.cursor}</span>
              {#if c.lag > 0}<span class="text-warn"> · {c.lag} sin confirmar</span>{/if}
            </li>
          {/each}
        </ul>
      {/if}
    </div>
  {/if}

  <div class="mt-3 rounded-md border border-line/70 p-2" aria-label="Conectar WhatsApp">
    <div class="flex items-center justify-between gap-2">
      <h4 class="text-[11px] font-medium text-ink-muted">Conectar WhatsApp</h4>
      {#if evo?.configured}
        <span class="text-[10.5px] {evo.state === 'connected' ? 'text-ok' : evo.state === 'unreachable' ? 'text-warn' : 'text-ink-muted'}">{stateLabel(evo.state)}</span>
      {/if}
    </div>
    {#if !evo}
      <p class="mt-1 text-[11px] text-ink-faint">Estado de conexión no disponible.</p>
    {:else if !evo.configured}
      <p class="mt-1 text-[11px] text-ink-faint">Instancia de WhatsApp no configurada en este servidor.</p>
    {:else if evo.state === "connected"}
      <p class="mt-1 text-[11px] text-ink-muted">La instancia {evo.instance} está conectada. No hace falta escanear nada.</p>
    {:else}
      <p class="mt-1 text-[11px] text-ink-muted">Escanea el QR con WhatsApp → Dispositivos vinculados → Vincular un dispositivo. Caduca en ~60 s.</p>
      {#if qr?.qr}
        <div class="mt-2 flex justify-center rounded-md bg-white p-2">
          <img src={qr.qr} alt="QR de vinculación de WhatsApp" class="h-48 w-48" />
        </div>
        {#if qr.code}<p class="mt-1 text-center text-[10.5px] text-ink-faint">Código de emparejamiento: <span class="tnum">{qr.code}</span></p>{/if}
      {/if}
      {#if qrError}<p role="status" class="mt-1 text-[11px] text-warn">{qrError}</p>{/if}
      <div class="mt-2 flex justify-end">
        <Button variant="outline" size="sm" onclick={refreshQr} disabled={qrBusy} aria-label="Generar QR de vinculación">
          <RefreshCw size={13} strokeWidth={2} class={qrBusy ? "animate-spin" : ""} aria-hidden="true" />
          {qr?.qr ? "Regenerar QR" : "Mostrar QR"}
        </Button>
      </div>
    {/if}
  </div>
</section>
